using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEditor.Animations;using System.IO;using System.Linq;
[InitializeOnLoad] public static class HunterCandidate {
 const string D="Assets/Demo/Characters/Hunter/";
 static HunterCandidate(){EditorApplication.delayCall+=Build;}
 static void Build(){if(File.Exists("Evidence/hunter-candidate-build.txt"))return;if(EditorApplication.isPlayingOrWillChangePlaymode)return;
 var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/SopaDopa/URP_Medieval_Fantasy/Constructor_URP.prefab");if(!source)return;
 var avatar=AssetDatabase.LoadAllAssetsAtPath("Assets/SopaDopa/URP_Medieval_Fantasy/Base_Char_Meshes/Constructor_2_1.fbx").OfType<Avatar>().FirstOrDefault();
 if(!avatar||!avatar.isValid||!avatar.isHuman){File.WriteAllText("Evidence/hunter-candidate-build.txt","FAIL Avatar "+avatar);return;}
 var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single); var root=new GameObject("Hunter Modular Candidate");var visual=Object.Instantiate(source,root.transform);visual.name="Visual";
 var chosen=new[]{"Body_Base","Body_Hands","Lether_tunic","Lether_pants","Lether_boot(left)","Lether_boot(right)","Lether_bracer_1(left)","Lether_bracer_1(right)","Lether_shold_1(left)","Lether_shold_2(right)","Lether_wide_belt","Leather_chest_belt_2","Hood_Cloth_1","Cape_1"};
 foreach(var r in visual.GetComponentsInChildren<SkinnedMeshRenderer>(true))r.gameObject.SetActive(chosen.Contains(r.name));
 var mats=new System.Collections.Generic.Dictionary<Material,Material>();foreach(var r in visual.GetComponentsInChildren<Renderer>(true)){r.sharedMaterials=r.sharedMaterials.Select(m=>{if(!m)return m;if(!mats.ContainsKey(m)){var n=new Material(m);n.name="Hunter_"+m.name; if(n.HasProperty("_BaseColor"))n.SetColor("_BaseColor",m.name.ToLower().Contains("misc")?new Color(.75f,.72f,.69f):new Color(.24f,.25f,.27f));AssetDatabase.CreateAsset(n,AssetDatabase.GenerateUniqueAssetPath(D+n.name+".mat"));mats[m]=n;}return mats[m];}).ToArray();}
 var animator=visual.GetComponent<Animator>();animator.avatar=avatar;animator.applyRootMotion=false;var controller=AnimatorController.CreateAnimatorControllerAtPath(AssetDatabase.GenerateUniqueAssetPath(D+"Hunter_Animator.controller"));
 string[] files={"Idle","Walking","Running"};string[] names={"Idle","Walk","Run"};for(int i=0;i<3;i++){var clip=AssetDatabase.LoadAllAssetsAtPath("Assets/Demo/Characters/Hunter_Validation_20261029/Mixamo/"+files[i]+".fbx").OfType<AnimationClip>().First(c=>!c.name.StartsWith("__"));var copy=Object.Instantiate(clip);copy.name=names[i];var settings=AnimationUtility.GetAnimationClipSettings(copy);settings.loopTime=true;settings.keepOriginalPositionXZ=true;settings.keepOriginalPositionY=true;settings.keepOriginalOrientation=true;settings.loopBlendPositionXZ=true;settings.loopBlendPositionY=true;settings.loopBlendOrientation=true;AnimationUtility.SetAnimationClipSettings(copy,settings);AssetDatabase.CreateAsset(copy,AssetDatabase.GenerateUniqueAssetPath(D+names[i]+".anim"));controller.layers[0].stateMachine.AddState(names[i]).motion=copy;}
 animator.runtimeAnimatorController=controller;var review=root.AddComponent<HunterReview>();review.animator=animator;
 PrefabUtility.SaveAsPrefabAsset(root,AssetDatabase.GenerateUniqueAssetPath(D+"Hunter_Modular.prefab"));
 var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.name="Neutral review floor";floor.transform.localScale=Vector3.one*2;var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.color=new Color(.15f,.16f,.17f);AssetDatabase.CreateAsset(fm,AssetDatabase.GenerateUniqueAssetPath(D+"ReviewFloor.mat"));floor.GetComponent<Renderer>().sharedMaterial=fm;
 var cam=new GameObject("Review Camera").AddComponent<Camera>();cam.tag="MainCamera";cam.transform.position=new Vector3(0,1.15f,3.6f);cam.transform.LookAt(Vector3.up);cam.fieldOfView=38;cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=new Color(.08f,.09f,.11f);review.reviewCamera=cam;
 var light=new GameObject("Neutral key").AddComponent<Light>();light.type=LightType.Directional;light.intensity=1.4f;light.transform.rotation=Quaternion.Euler(40,160,0);RenderSettings.ambientLight=new Color(.55f,.55f,.55f);
 EditorSceneManager.SaveScene(scene,AssetDatabase.GenerateUniqueAssetPath("Assets/Demo/Scenes/HunterCharacterReview.unity"));AssetDatabase.SaveAssets();File.WriteAllText("Evidence/hunter-candidate-build.txt","Avatar valid human: "+avatar.name+"\nEnabled: "+string.Join(", ",chosen)+"\nOriginal skinning retained. RootMotion disabled.\n");
 }
}
